// Single import point for Wails bindings.
// The wailsjs folder is generated by `wails dev` / `wails build`.
//
// Nothing here fires analytics. Product events are emitted inside the Go
// bindings themselves (see internal/analytics), which is strictly better:
// the Go side sees the real outcome and duration of an operation rather
// than the intent to start one, it cannot be bypassed by a new caller, and
// it keeps working while the machine is offline.
//
// Events that only the UI can observe — panel opens, AI acceptance, banner
// clicks — go through ./analytics, which forwards them to the same Go
// emitter.
import * as App from "../wailsjs/go/main/App";
import { isBetaEnabled } from "./updateChannel";

